// The command box's search on the REAL KJV (wave-2-layout.md 6). Results come
// from src-tauri/tests/golden/kjv-search.json, machine-generated by the Rust
// core (search.rs) from pipeline/out through open_verified: verse text read
// from kjv.sqlite, emphasis runs from match_spans. No Scripture is typed here.
//
// - render: every result's DOM text equals the stored text, the <mark>s equal
//   match_spans, the .wj spans equal the stored red pieces, and red text inside
//   a mark is still red;
// - the dropdown: reference / ambiguous / search rows, paging, no results,
//   unavailable, Enter jumps with a flash, Ctrl+F reopens, F3 steps, ARIA.
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { flushSync, mount, unmount } from "svelte";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { kjv } from "./kjv-golden";
import { cp, textNodes } from "./render-check";
import { renderResultText } from "../src/lib/verse-dom";
import type { HitRun, SearchHit } from "../src/lib/types";

interface GQuery { query: string; total: number; exact_total: number; phrase: boolean; hits: SearchHit[]; spans: [number, number][][] }
const golden: GQuery[] = JSON.parse(readFileSync(resolve(process.cwd(), "src-tauri/tests/golden/kjv-search.json"), "utf8"));
const CSS =
  readFileSync(resolve(process.cwd(), "src/styles/tokens.css"), "utf8") +
  readFileSync(resolve(process.cwd(), "src/styles/app.css"), "utf8");

const calls: { cmd: string; args: Record<string, unknown> }[] = [];
const mode = { searchAvailable: true };
const SEARCH_ERROR = "content file failed its checksum (damaged or replaced): kjv-search.sqlite";
const PAGEN = 20;

/** The golden's answer for a query; "lord god" is paged by repeating its golden hits (positions differ). */
function answer(query: string, offset: number) {
  const g = golden.find((x) => x.query === query);
  if (!g) return { status: "ok", total: 0, exact_total: 0, offset, phrase: false, hits: [] };
  const hits: SearchHit[] = [];
  for (let i = offset; i < Math.min(g.total, offset + PAGEN); i++) {
    if (g.total <= g.hits.length) { if (g.hits[i]) hits.push(g.hits[i]); }
    else hits.push(g.hits[i % g.hits.length]);
  }
  return { status: "ok", total: g.total, exact_total: g.exact_total, offset, phrase: g.phrase, hits };
}

/** A chapter for the reader: from the render golden, or the result verses of that chapter. */
function chapterFor(book: number, chapter: number) {
  const c = kjv.chapters.find((x) => x.book === book && x.chapter === chapter);
  if (c) return { book, osis: c.osis, chapter, verses: c.verses.map(({ v, text, runs }) => ({ v, text, runs })) };
  const vs = new Map<number, { v: number; text: string; runs: unknown[] }>();
  for (const g of golden) for (const h of g.hits) {
    if (h.book === book && h.chapter === chapter)
      vs.set(h.verse, { v: h.verse, text: h.text, runs: h.runs.map(({ hit: _h, ...r }) => r) });
  }
  if (!vs.size) throw "not found";
  const osis = kjv.books.find((b) => b.ord === book)!.osis;
  return { book, osis, chapter, verses: [...vs.values()].sort((a, b) => a.v - b.v) };
}

vi.mock("@tauri-apps/api/core", () => ({
  invoke: async (cmd: string, args: Record<string, unknown> = {}) => {
    calls.push({ cmd, args });
    switch (cmd) {
      case "app_info":
        return {
          content_error: null, user_error: null, translations: [kjv.translation], lexicon_available: true, lexicon_error: null,
          search_available: mode.searchAvailable, search_error: mode.searchAvailable ? null : SEARCH_ERROR,
        };
      case "list_books": return kjv.books;
      case "get_chapter": return chapterFor(args.book as number, args.chapter as number);
      case "get_highlights": return [];
      case "load_state":
        return {
          position: { translation: "KJV", book: "John", chapter: 3, anchor_verse: null, anchor_frac: null, current_verse: null },
          settings: { verse_numbers: true, red_letters: true, supplied_italics: true, text_step: 5, panel_open: false, right_width_rem: 22, right_split: 0.5 },
        };
      case "bookmarks_list": return [];
      case "bookmark_set": case "bookmark_restore": return null;
      case "bookmark_clear": return null;
      case "save_state": return null;
      case "search":
        if (!mode.searchAvailable) return { status: "unavailable", reason: SEARCH_ERROR };
        return answer(args.query as string, args.offset as number);
    }
    throw new Error(`unexpected command ${cmd}`);
  },
}));

const settle = async (ms = 0) => {
  for (let i = 0; i < 5; i++) { await new Promise((r) => setTimeout(r, ms)); flushSync(); }
};
const $ = <T extends Element = HTMLElement>(s: string) => document.querySelector<T>(s);
const $$ = <T extends Element = HTMLElement>(s: string) => Array.from(document.querySelectorAll<T>(s));
const key = (target: EventTarget, k: string, init: KeyboardEventInit = {}) =>
  target.dispatchEvent(new KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true, ...init }));

let styleEl: HTMLStyleElement;
beforeAll(() => {
  styleEl = document.createElement("style");
  styleEl.textContent = CSS;
  document.head.appendChild(styleEl);
});

/** Code-point ranges of a container's text inside elements matching `sel`. */
function rangesOf(root: HTMLElement, sel: string): [number, number][] {
  const out: [number, number][] = [];
  let pos = 0;
  for (const t of textNodes(root)) {
    const n = cp(t.data).length;
    if (t.parentElement!.closest(sel) && root.contains(t.parentElement!.closest(sel))) {
      const last = out[out.length - 1];
      if (last && last[1] === pos) last[1] = pos + n; else out.push([pos, pos + n]);
    }
    pos += n;
  }
  return out;
}

/** Stored red pieces of a result, from its runs (one range per `rp`). */
function redPieces(runs: HitRun[]): [number, number][] {
  const out: [number, number][] = [];
  let pos = 0, lastRp: number | undefined;
  for (const r of runs) {
    const n = cp(r.text).length;
    if (r.rp !== undefined && r.rp === lastRp) out[out.length - 1][1] = pos + n;
    else if (r.rp !== undefined) out.push([pos, pos + n]);
    lastRp = r.rp;
    pos += n;
  }
  return out;
}

function renderHit(h: SearchHit): HTMLElement {
  const row = document.createElement("div");
  row.className = "opt-row cmd-result";
  const el = document.createElement("div");
  el.className = "rtext";
  row.appendChild(el);
  document.body.appendChild(row);
  renderResultText(el, h.runs);
  return el;
}

function checkHit(el: HTMLElement, h: SearchHit, spans: [number, number][], red: string): string[] {
  const p: string[] = [];
  if (el.textContent !== h.text) p.push(`${h.reference}: DOM text differs from stored text`);
  if (JSON.stringify(rangesOf(el, "mark.hit")) !== JSON.stringify(spans)) p.push(`${h.reference}: marks differ from match_spans`);
  // the .wj spans: one per stored red piece, same ranges
  const wj = Array.from(el.querySelectorAll(".wj")).map((w) => cp(w.textContent ?? "").length);
  if (JSON.stringify(wj) !== JSON.stringify(redPieces(h.runs).map(([s, e]) => e - s))) p.push(`${h.reference}: .wj differs from red pieces`);
  for (const e of el.querySelectorAll("*")) {
    const ok = (e.tagName === "SPAN" && ["wj", "add", "nd"].includes(e.className)) || (e.tagName === "MARK" && e.className === "hit");
    if (!ok || e.attributes.length !== 1) p.push(`${h.reference}: unexpected <${e.tagName.toLowerCase()} class="${e.className}">`);
    if (e.tagName === "MARK" && e.querySelector("*")) p.push(`${h.reference}: a mark is not innermost`);
  }
  // red letters keep their colour inside a mark
  for (const t of textNodes(el)) {
    const inRed = !!t.parentElement!.closest(".wj");
    const c = getComputedStyle(t.parentElement!).color.toLowerCase();
    if (inRed && c !== red.toLowerCase()) p.push(`${h.reference}: red text is ${c}`);
  }
  return p;
}

describe("search result render test (real KJV)", () => {
  it("the golden covers red letters inside matches, the divine name, supplied words and a phrase", () => {
    const all = golden.flatMap((g) => g.hits);
    expect(golden.map((g) => g.query)).toContain("jesus wept");
    expect(all.some((h) => h.runs.some((r) => r.red && r.hit))).toBe(true);
    expect(all.some((h) => h.runs.some((r) => r.nd && r.hit))).toBe(true);
    expect(all.some((h) => h.runs.some((r) => r.add))).toBe(true);
    expect(golden.some((g) => g.phrase)).toBe(true);
    expect(all.every((h) => h.emphasised)).toBe(true);
  });

  it("DOM text = stored text, marks = match_spans, .wj = red pieces, red stays red inside marks", () => {
    const red = getComputedStyle(document.documentElement).getPropertyValue("--color-red-letter").trim();
    expect(red).not.toBe("");
    const problems: string[] = [];
    let marks = 0;
    for (const g of golden) g.hits.forEach((h, i) => {
      const el = renderHit(h);
      problems.push(...checkHit(el, h, g.spans[i], red));
      marks += el.querySelectorAll("mark.hit").length;
      el.parentElement!.remove();
    });
    expect(problems).toEqual([]);
    expect(marks).toBeGreaterThan(20);
    // the match colour never sets a text colour
    expect(CSS).toMatch(/\.cmd-result mark\.hit \{[^}]*color: inherit;/);
  });

  it("the check bites (a shifted mark, a changed character)", () => {
    const red = getComputedStyle(document.documentElement).getPropertyValue("--color-red-letter").trim();
    const g = golden[0], h = g.hits[0];
    const el = renderHit(h);
    expect(checkHit(el, h, g.spans[0], red)).toEqual([]);
    expect(checkHit(el, h, g.spans[0].map(([s, e]) => [s + 1, e] as [number, number]), red).length).toBeGreaterThan(0);
    expect(checkHit(el, { ...h, text: h.text + " " }, g.spans[0], red).length).toBeGreaterThan(0);
    el.parentElement!.remove();
  });
});

let app: ReturnType<typeof mount> | null = null;
async function start() {
  if (app) unmount(app);
  document.body.innerHTML = '<div id="app"></div>';
  const { default: App } = await import("../src/App.svelte");
  app = mount(App, { target: $("#app")! });
  await settle();
}
afterAll(() => { if (app) unmount(app); });

async function type(text: string) {
  const input = $<HTMLInputElement>("#cmd-input")!;
  if (document.activeElement !== input) { input.focus(); await settle(); }
  input.value = text;
  input.dispatchEvent(new Event("input", { bubbles: true }));
  await settle(60); // past the 150ms debounce
}
const input = () => $<HTMLInputElement>("#cmd-input")!;
const activeRow = () => document.getElementById(input().getAttribute("aria-activedescendant") ?? "");
const searches = () => calls.filter((c) => c.cmd === "search");

describe("command box search (wave-2-layout.md 6)", () => {
  it("a reference never searches; text that isn't one does", async () => {
    await start();
    calls.length = 0;
    await type("jn 3 16");
    expect($("#cmd-pop")?.textContent).toContain("John 3:16");
    expect($(".cmd-h")).toBeNull();
    await type("jn 99");
    expect($("#cmd-err")?.textContent).toContain("John has 21 chapters.");
    expect(searches().length).toBe(0);
    await type("jesus wept");
    expect(searches().map((c) => c.args)).toEqual([{ translation: "KJV", query: "jesus wept", scope: "bible", offset: 0, limit: 20 }]);
    const g = golden.find((x) => x.query === "jesus wept")!;
    expect($(".cmd-h")?.textContent).toBe(`Verses · ${g.total} in the KJV`);
    expect($$(".cmd-result").length).toBe(g.total);
    expect($(".cmd-result .ref")?.textContent).toContain("John 11:35");
    // exact phrase first, then all the words, each named
    expect($$(".cmd-subh").map((e) => e.textContent?.trim())).toEqual([
      `Exact phrase · ${g.exact_total}`, `All the words · ${g.total - g.exact_total}`,
    ]);
    // ARIA: one listbox, sections are labelled groups, the active row is the active descendant
    expect($('[role="listbox"]')?.getAttribute("aria-label")).toBe("Go to or search");
    const grp = $('[role="group"]')!;
    expect(document.getElementById(grp.getAttribute("aria-labelledby")!)?.textContent).toContain("Verses");
    expect(activeRow()?.classList.contains("cmd-result")).toBe(true);
    expect(activeRow()?.getAttribute("aria-selected")).toBe("true");
    // no copy of the verse in an attribute
    expect(activeRow()?.getAttribute("aria-label")).toBeNull();
  });

  it("Enter jumps to the first result: chapter shown, verse current and flashing, focus in the pane", async () => {
    key(input(), "Enter");
    await settle();
    expect($(".chapter-head")?.textContent).toBe("John 11");
    const v = $('.verse[data-v="35"]')!;
    expect(v.getAttribute("aria-current")).toBe("true");
    expect(v.classList.contains("flashing")).toBe(true);
    expect(document.activeElement?.classList.contains("reader-scroll")).toBe(true);
    expect($("#cmd-pop")).toBeNull();
    // the flash ends on animationend
    const ev = new Event("animationend", { bubbles: true }) as AnimationEvent;
    Object.defineProperty(ev, "animationName", { value: "verse-flash" });
    v.dispatchEvent(ev);
    expect(v.classList.contains("flashing")).toBe(false);
  });

  it("F3 and Shift+F3 step through the last search outside the field, with a toast; past the end it wraps", async () => {
    const pane = $(".reader-scroll")!;
    pane.focus();
    key(pane, "F3");
    await settle();
    const g = golden.find((x) => x.query === "jesus wept")!;
    expect($(".toast")?.textContent).toBe(`${g.hits[1].reference} · 2 of ${g.total}`);
    expect(document.activeElement).toBe(pane); // focus stays
    key(pane, "F3");
    await settle();
    key(pane, "F3");
    await settle();
    expect($(".toast")?.textContent).toBe(`Back to the first result · ${g.hits[0].reference} · 1 of ${g.total}`);
    key(pane, "F3", { shiftKey: true });
    await settle();
    expect($(".toast")?.textContent).toBe(`Back to the last result · ${g.hits[g.total - 1].reference} · ${g.total} of ${g.total}`);
  });

  it("Ctrl+F reopens the last search in search mode, its last result active", async () => {
    key(document.body, "f", { ctrlKey: true });
    await settle();
    expect(document.activeElement).toBe(input());
    expect(input().value).toBe("jesus wept");
    expect(input().getAttribute("aria-label")).toBe("Search the Bible");
    expect($(".cmd-chip")?.textContent).toBe("Search");
    const g = golden.find((x) => x.query === "jesus wept")!;
    expect(activeRow()?.querySelector(".ref")?.textContent).toContain(g.hits[g.total - 1].reference);
    key(input(), "Escape");
    await settle();
  });

  it("a bare book name shows Go to and Verses; with no verses, Go to alone", async () => {
    await type("Job");
    expect($("#cmd-h-go")?.textContent).toBe("Go to");
    expect(activeRow()?.textContent).toContain("Job");
    expect($("#cmd-h-verses")).toBeNull(); // no results for this text in the mock
    expect($(".cmd-msg")).toBeNull(); // and no "no verses" message
    expect(searches().at(-1)?.args.query).toBe("Job");
  });

  it("search mode (Ctrl+F) never parses a reference; Backspace in the empty field leaves it", async () => {
    key(input(), "Escape");
    await settle();
    key(document.body, "f", { ctrlKey: true });
    await settle();
    await type("jn 3 16");
    expect($("#cmd-pop")?.textContent).not.toContain("John 3:16");
    expect(searches().at(-1)?.args.query).toBe("jn 3 16");
    await type("");
    key(input(), "Backspace");
    await settle();
    expect($(".cmd-chip")).toBeNull();
    expect(input().getAttribute("aria-label")).toBe("Go to a passage or search");
    key(input(), "Escape");
    await settle();
  });

  it("a leading quote mark is an exact phrase", async () => {
    const g = golden.find((x) => x.phrase && x.total > 1)!;
    await type(g.query);
    expect($(".cmd-chip")?.textContent).toBe("Search");
    expect($$(".cmd-result").length).toBe(Math.min(20, g.total));
    expect($(".cmd-subh")).toBeNull(); // a phrase has one group only
  });

  it("no results: the message echoes the query; nothing to choose", async () => {
    await type("jesus wpet");
    expect($(".cmd-msg .l1")?.textContent).toBe("No verses in the KJV contain “jesus wpet”.");
    expect($('[role="option"]')).toBeNull();
  });

  it("many results: 20, then Show 20 more appends in place and makes the first new one active", async () => {
    const g = golden.find((x) => x.query === "lord god")!;
    await type("lord god");
    expect($(".cmd-h")?.textContent).toBe(`Verses · ${g.total} in the KJV`);
    expect($$(".cmd-result").length).toBe(20);
    const more = $(".cmd-more")!;
    expect(more.textContent).toContain("Show 20 more");
    expect(more.textContent).toContain(`20 of ${g.total}`);
    key(input(), "End", { ctrlKey: true });
    await settle();
    expect(activeRow()).toBe(more);
    key(input(), "Enter");
    await settle();
    expect($$(".cmd-result").length).toBe(40);
    expect(activeRow()?.id).toBe("cmd-opt-hit-20");
    expect(searches().at(-1)?.args.offset).toBe(20);
    // arrows stop at the ends
    key(input(), "Home", { ctrlKey: true });
    await settle();
    key(input(), "ArrowUp");
    await settle();
    expect(activeRow()?.id).toBe("cmd-opt-hit-0");
    key(input(), "Escape");
    await settle();
  });

  it("an unavailable index says so in place of Verses; references still work", async () => {
    mode.searchAvailable = false;
    await start();
    await type("jesus wept");
    expect($(".cmd-msg .l1")?.textContent).toContain("Search is unavailable");
    expect($(".cmd-msg .l2")?.textContent).toBe(`Details: ${SEARCH_ERROR}`);
    expect($(".cmd-result")).toBeNull();
    await type("jn 3 16");
    key(input(), "Enter");
    await settle();
    expect($(".chapter-head")?.textContent).toBe("John 3");
    mode.searchAvailable = true;
  });
});
